const crypto = require('crypto');

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const allowedSources = new Set([
  'website_form',
  'demo_form',
  'test_client',
  'gmail',
]);

function text(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function optionalText(value) {
  const normalized = text(value);
  return normalized || null;
}

function stableStringify(value) {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`;
  }

  const keys = Object.keys(value).sort();

  return `{${keys
    .map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`)
    .join(',')}}`;
}

function validHttpUrl(value) {
  if (!value) return true;
  if (typeof value !== 'string') return false;

  const candidate = value.trim();

  return /^https?:\/\/[a-z0-9.-]+(?::\d{1,5})?(?:[/?#][^\s]*)?$/i.test(
    candidate,
  );
}

return $input.all().map((item) => {
  const raw = JSON.parse(JSON.stringify(item.json));
  const validationErrors = [];

  const submissionId = text(raw.submission_id);
  const submittedAt = text(raw.submitted_at);
  const firstName = text(raw.first_name);
  const lastName = text(raw.last_name);
  const emailOriginal = text(raw.email);
  const emailNormalized = emailOriginal.toLowerCase();
  const companyName = text(raw.company_name);
  const message = text(raw.message);
  const source = text(raw.source);

  const jobTitle = optionalText(raw.job_title);
  const website = optionalText(raw.website);
  const phone = optionalText(raw.phone);
  const countryCode = optionalText(raw.country_code)?.toUpperCase() ?? null;
  const budgetCurrency =
    optionalText(raw.budget_currency)?.toUpperCase() ?? null;

  const companySize =
    raw.company_size === undefined || raw.company_size === null
      ? null
      : raw.company_size;

  const budgetAmount =
    raw.budget_amount === undefined || raw.budget_amount === null
      ? null
      : raw.budget_amount;

  const submissionIdValid = uuidPattern.test(submissionId);

  function addError(field, code, messageText) {
    validationErrors.push({
      field,
      code,
      message: messageText,
    });
  }

  if (!submissionIdValid) {
    addError(
      'submission_id',
      'invalid_uuid',
      'submission_id must be a valid UUID',
    );
  }

  if (
    !submittedAt ||
    !/^\d{4}-\d{2}-\d{2}T/.test(submittedAt) ||
    Number.isNaN(Date.parse(submittedAt))
  ) {
    addError(
      'submitted_at',
      'invalid_timestamp',
      'submitted_at must be a valid ISO 8601 timestamp',
    );
  }

  if (firstName.length < 1 || firstName.length > 100) {
    addError(
      'first_name',
      'invalid_length',
      'first_name must contain 1 to 100 characters',
    );
  }

  if (lastName.length < 1 || lastName.length > 100) {
    addError(
      'last_name',
      'invalid_length',
      'last_name must contain 1 to 100 characters',
    );
  }

  if (!emailPattern.test(emailNormalized) || emailNormalized.length > 320) {
    addError(
      'email',
      'invalid_email',
      'email must be syntactically valid',
    );
  }

  if (companyName.length < 1 || companyName.length > 150) {
    addError(
      'company_name',
      'invalid_length',
      'company_name must contain 1 to 150 characters',
    );
  }

  if (message.length < 20 || message.length > 2000) {
    addError(
      'message',
      'invalid_length',
      'message must contain 20 to 2000 characters',
    );
  }

  if (raw.consent !== true) {
    addError(
      'consent',
      'consent_required',
      'consent must be true',
    );
  }

  if (!allowedSources.has(source)) {
    addError(
      'source',
      'invalid_source',
      'source is not allowed',
    );
  }

  if (
    companySize !== null &&
    (!Number.isInteger(companySize) || companySize <= 0)
  ) {
    addError(
      'company_size',
      'invalid_integer',
      'company_size must be a positive integer',
    );
  }

  if (
    budgetAmount !== null &&
    (typeof budgetAmount !== 'number' ||
      !Number.isFinite(budgetAmount) ||
      budgetAmount < 0)
  ) {
    addError(
      'budget_amount',
      'invalid_number',
      'budget_amount must be zero or a positive number',
    );
  }

  if (website && !validHttpUrl(website)) {
    addError(
      'website',
      'invalid_url',
      'website must be a valid HTTP or HTTPS URL',
    );
  }

  if (countryCode && !/^[A-Z]{2}$/.test(countryCode)) {
    addError(
      'country_code',
      'invalid_country_code',
      'country_code must contain two uppercase letters',
    );
  }

  if (budgetCurrency && !/^[A-Z]{3}$/.test(budgetCurrency)) {
    addError(
      'budget_currency',
      'invalid_currency',
      'budget_currency must contain three uppercase letters',
    );
  }

  if (jobTitle && jobTitle.length > 150) {
    addError(
      'job_title',
      'invalid_length',
      'job_title must not exceed 150 characters',
    );
  }

  const normalizedPayload = {
    submission_id: submissionId,
    submitted_at: submittedAt,
    first_name: firstName,
    last_name: lastName,
    email: emailNormalized,
    company_name: companyName,
    job_title: jobTitle,
    company_size: companySize,
    website,
    phone,
    country_code: countryCode,
    budget_currency: budgetCurrency,
    budget_amount: budgetAmount,
    message,
    consent: raw.consent,
    source,
  };

  const payloadHash = crypto
    .createHash('sha256')
    .update(stableStringify(normalizedPayload))
    .digest('hex');

  const isValid = validationErrors.length === 0;

  return {
    json: {
      ...normalizedPayload,
      email_original: emailOriginal,
      email_normalized: emailNormalized,
      correlation_id: crypto.randomUUID(),
      raw_payload: raw,
      normalized_payload: normalizedPayload,
      payload_hash: payloadHash,
      validation_errors: validationErrors,
      submission_id_valid: submissionIdValid,
      is_valid: isValid,
      target_status: isValid ? 'AI_PENDING' : 'INVALID',
    },
  };
});
